#include "tps274c65.h"
#include "../../config.mcc/mcc_generated_files/system/system.h"
#include "../registers.h"
#include "tps274c65_regs.h"
#include "SpiHelper.h"
#include <stdint.h>
#include <util/delay.h>

static uint8_t sw_in_shadow = 0x00; // Registre SW_IN_REG (Commutateurs)

static volatile uint8_t tps_spi_timeout_count = 0;

static inline void TPS274C65_Select(void) { IO_CS_TPS_SetLow(); }

static inline void TPS274C65_Deselect(void) { IO_CS_TPS_SetHigh(); }

static uint16_t tps_SendMessage(uint16_t cmd_dir, uint8_t spi_addr,
                                uint8_t addr, uint8_t data) {
  // Le TSP274C65AS est en 24bit
  // Trame READ :
  // A1 A2 A3 R(0) CH4 CH3 CH2 CH1    RSVD RA6 RA5 RA4 RA3 RA2 RA1 RA0
  //      0 0 0 0 0 0 0 0
  // Réponse :

  // Trame WRITE
  // A1 A2 A3 W(1) CH4 CH3 CH2 CH1    RSVD RA6 RA5 RA4 RA3 RA2 RA1 RA0
  //      D7 D6 D5 D3 D2 D1
  // Réponse :

  uint8_t buf_data[3];

  buf_data[0] = ((spi_addr & 0x07) << 5) | cmd_dir | (sw_in_shadow & 0x0F);
  buf_data[1] = addr;
  buf_data[2] = data;

  // 2. Transaction SPI
  TPS274C65_Select();
  if (!Spi0Helper_BufferExchange(buf_data, sizeof buf_data)) {
    tps_spi_timeout_count++;
  }
  TPS274C65_Deselect();

  // 3. Reconstruction du mot RX 16-bit reçu
  return ((uint16_t)buf_data[0] << 8) | buf_data[1];
}

void TPS274C65_Init(void) {
  // Initialisation du TPS274C65
  sw_in_shadow = 0x00; // Commutateurs à 0

  tps_SendMessage(TPS_SPI_CMD_READ, 0x00, 0x02, 0x00);        // Clear all fault
  tps_SendMessage(TPS_SPI_CMD_WRITE, 0x00, 0x23, 0b10000000); // RCB Disabled
  tps_SendMessage(TPS_SPI_CMD_WRITE, 0x00, 0x27,
                  0b00000001); // No UV Warning on fault pin
}

/**
 * @ingroup  tps274c65
 * @brief Refresh must be call in the main loop
 */
void TPS274C65_SendOutputs(void) {
  sw_in_shadow = output_process_ram[OUTPUT_PROCESS_RELAYS] & 0x0F;
  uint8_t led_1_4_shadow =
      output_process_ram[OUTPUT_PROCESS_LEDS] & 0x0F; // LEDs 1 à 4
  uint8_t led_5_8_shadow = output_process_ram[OUTPUT_PROCESS_LEDS] >> 4; // LEDs 5 à 8

  // Update Channels
  tps_SendMessage(TPS_SPI_CMD_WRITE, 0x00, TPS_REG_SW_STATE, sw_in_shadow);
  // Update Leds
  tps_SendMessage(TPS_SPI_CMD_WRITE, 0x00, TPS_REG_LED1_4_CTL, led_1_4_shadow);
  tps_SendMessage(TPS_SPI_CMD_WRITE, 0x00, TPS_REG_LED5_8_CTL, led_5_8_shadow);
}
